   {plan?<div className="escala-statusbar"><span className={'escala-pill '+plan.status.toLowerCase()}>{plan.status==='DRAFT'?'Rascunho':plan.status==='APPROVED'?'Aprovada':'Bloqueada'}</span><span>Revisão {plan.revision}{dirty?' · alterações neste aparelho':''}</span><div>{canApprove&&plan.status==='DRAFT'?<button disabled={busy||dirty||issues.some(i=>i.severity==='ERROR')} onClick={()=>void run(async()=>{await send('APPROVE',{month:selectedMonth},plan.id,plan.revision);await reload(false);setNotice('Escala aprovada e protegida contra alterações automáticas.');})}>Aprovar escala</button>:null}{canApprove&&plan.status==='APPROVED'?<button disabled={busy} onClick={()=>void run(async()=>{await send('LOCK',{month:selectedMonth},plan.id,plan.revision);await reload(false);})}>Bloquear escala</button>:null}{isAdmin&&plan.status!=='DRAFT'?<button disabled={busy} onClick={()=>{const reason=prompt('Justificativa para desbloquear a escala:');if(reason?.trim())void run(async()=>{await send('UNLOCK',{month:selectedMonth,reason},plan.id,plan.revision);await reload(false);});}}>Desbloquear para editar</button>:null}<details className="escala-tools"><summary>Imprimir e exportar</summary><div><button onClick={()=>window.print()}>Imprimir</button><button disabled={busy} onClick={()=>void run(()=>downloadPdf(adapter,data,plan))}>Exportar PDF</button><button onClick={()=>void adapter.download(`Escala-${selectedMonth.slice(0,7)}.csv`,new Blob([csv(exportMatrix(data,plan))],{type:'text/csv;charset=utf-8'}))}>Excel / CSV</button></div></details></div></div>:null}
