 if(entity==='TRUCK')fields=[{key:'label',label:'Identificação do caminhão',required:true},{key:'plate',label:'Placa',required:values.status==='AVAILABLE'},{key:'team_id',label:'Equipe preferencial',kind:'select',choices:teams},{key:'status',label:'Situação',kind:'select',choices:choices({AVAILABLE:'Disponível',MAINTENANCE:'Manutenção',UNAVAILABLE:'Indisponível'}),required:true},{key:'notes',label:'Observações',kind:'textarea'}];
