 function update(f:FormField,value:unknown){setValues(current=>{const next={...current,[f.key]:value};if(f.key==='profile_id'){const profile=state.profiles.find(p=>p.id===value);if(profile){next.name=profile.name;next.job=/MOTORISTA|COLABORADOR_ENTREGA/.test(profile.role)?'Motorista':/AJUDANTE/.test(profile.role)?'Ajudante':profile.role.replaceAll('_',' ');}}return next;});}
