 const holidays=data.holidays.filter(h=>h.enabled&&h.date===day.date),special=specialSaturday(data,day.date);
 return <form className="escala-dialog-body escala-day-editor" onSubmit={e=>{e.preventDefault();onSave({...draft,manual:true},reason);}}><div className="escala-day-summary"><strong>{weekdayNames[weekday(day.date)]}</strong><span>{draft.duties.filter(d=>d.mode==='ROUTE').length} em rota · {draft.duties.filter(d=>d.mode==='REST').length} de folga · {draft.duties.filter(d=>d.mode==='UNAVAILABLE').length} indisponível(is)</span>{holidays.map(h=><span key={h.id}>{h.name}</span>)}{special.map(h=><span key={h.id}>Sábado anterior a {h.name} ({date(h.date)})</span>)}</div><div className="table-wrap"><table><thead><tr><th>Equipe e integrantes</th><th>Situação</th><th>Caminhão</th><th>Ações</th></tr></thead><tbody>{draft.duties.map(d=><tr key={d.team_id}><td><strong>{teamName(data,d.team_id)}</strong>{d.members.map(p=><small key={p.id}>{p.name} · {p.job}</small>)}</td><td>{editable?<select aria-label={'Situação de '+teamName(data,d.team_id)} value={d.mode} onChange={e=>changeDuty(d.team_id,{mode:e.target.value as Duty['mode'],truck_id:e.target.value==='ROUTE'?d.truck_id:null})}>{Object.entries(modeNames).map(([value,label])=><option key={value} value={value}>{label}</option>)}</select>:modeNames[d.mode]}</td><td>{editable&&d.mode==='ROUTE'?<select aria-label={'Caminhão de '+teamName(data,d.team_id)} value={d.truck_id||''} onChange={e=>changeDuty(d.team_id,{truck_id:e.target.value||null})}><option value="">Selecione</option>{visible(data.trucks).filter(t=>t.status==='AVAILABLE').map(t=><option key={t.id} value={t.id}>{t.label} · {t.plate}</option>)}</select>:data.trucks.find(t=>t.id===d.truck_id)?.plate||'—'}</td><td>{editable&&d.mode==='REST'&&weekday(day.date)!==0?<button type="button" onClick={()=>onMove(d.team_id)}>Movimentar folga</button>:null}{canEdit&&d.mode==='ROUTE'&&d.id&&day.date<=today()?<button type="button" disabled={busy} onClick={()=>onComplete(d)}>{d.completed?'✓ Realizada (corrigir)':'Confirmar rota realizada'}</button>:null}</td></tr>)}</tbody></table></div>{editable?<><div className="escala-form-grid"><label>Equipes necessárias<input type="number" min="0" max="100" value={draft.required} onChange={e=>setDraft({...draft,required:Number(e.target.value)})}/></label><label className="escala-checkbox-field"><span>Operação especial confirmada</span><input type="checkbox" checked={draft.confirmed} onChange={e=>setDraft({...draft,confirmed:e.target.checked})}/></label><label className="escala-checkbox-field"><span>Preservar este dia nos próximos sorteios</span><input type="checkbox" checked={draft.locked} onChange={e=>setDraft({...draft,locked:e.target.checked})}/></label><label className="escala-wide">Observações<textarea value={draft.notes} maxLength={3000} onChange={e=>setDraft({...draft,notes:e.target.value})}/></label><label className="escala-wide">Justificativa da alteração *<textarea required value={reason} maxLength={2000} onChange={e=>setReason(e.target.value)}/></label></div><footer><button className="primary" disabled={busy}>Validar e salvar alteração</button></footer></>:<p>{day.locked?'Dia bloqueado para alterações. ':''}As confirmações de rotas realizadas são registradas separadamente do planejamento aprovado.</p>}</form>;
