function Reports({data,plan,month,adapter}:{data:EscalaState;plan:MonthPlan|null;month:string;adapter:EscalaAdapter}){
 const [compare,setCompare]=useState(plusDays(month,-1).slice(0,7)),[scope,setScope]=useState('month');const days=scope==='history'?[...data.history,...(plan?.days||[])]:plan?.days||[],stats=statistics(data,days),other=statistics(data,data.history.filter(d=>d.date.startsWith(compare))),total=days.flatMap(d=>d.duties),staff=new Map<string,{name:string;rest:number;work:number;route:number;done:number}>();
 for(const day of days)for(const duty of day.duties)for(const p of duty.members){const row=staff.get(p.id)||{name:p.name,rest:0,work:0,route:0,done:0};if(duty.mode==='REST')row.rest++;if(duty.mode==='ROUTE'||duty.mode==='RESERVE')row.work++;if(duty.mode==='ROUTE')row.route++;if(duty.completed)row.done++;staff.set(p.id,row);}
 return <><div className="escala-page-actions"><h2>Distribuição de folgas e operação</h2><label>Período<select value={scope} onChange={e=>setScope(e.target.value)}><option value="month">Mês selecionado</option><option value="history">Histórico aprovado + mês selecionado</option></select></label><label>Comparar com<input type="month" value={compare} onChange={e=>setCompare(e.target.value)}/></label><button onClick={()=>void adapter.download(`Relatorio-Escala-${month.slice(0,7)}.csv`,new Blob([csv([['Equipe','Folgas','Dias trabalhados','Rotas programadas','Domingos','Sábados','Feriados','Indisponibilidades'],...stats.map(s=>[s.team.name,s.total,s.worked,s.routes,s.weekdays[0],s.weekdays[6],s.holidays,s.unavailable])])],{type:'text/csv;charset=utf-8'}))}>Exportar relatório</button></div><div className="escala-kpis">{[['◷','Folgas',total.filter(d=>d.mode==='REST').length],['↗','Rotas programadas',total.filter(d=>d.mode==='ROUTE').length],['✓','Rotas confirmadas como realizadas',total.filter(d=>d.completed).length],['!','Indisponibilidades',total.filter(d=>d.mode==='UNAVAILABLE').length]].map(([icon,label,value])=><article className="escala-panel" key={String(label)}><span>{icon}</span><div><small>{label}</small><strong>{value}</strong></div></article>)}</div><section className="escala-panel"><h3>Folgas por equipe</h3><div className="escala-chart">{stats.map(s=><div key={s.team.id}><span>{s.team.name}</span><meter min="0" max={Math.max(1,...stats.map(x=>x.total))} value={s.total}>{s.total}</meter><strong>{s.total}</strong><small>{compare}: {other.find(o=>o.team.id===s.team.id)?.total||0}</small></div>)}</div></section><section className="escala-panel"><h3>Equilíbrio por dia da semana</h3><div className="table-wrap"><table><thead><tr><th>Equipe</th><th>Folgas</th>{weekdayNames.map(w=><th key={w}>{w.slice(0,3)}</th>)}<th>Feriados</th><th>Dias trabalhados</th></tr></thead><tbody>{stats.map(s=><tr key={s.team.id}><td>{s.team.name}</td><td>{s.total}</td>{s.weekdays.map((n,i)=><td key={i}>{n}</td>)}<td>{s.holidays}</td><td>{s.worked}</td></tr>)}</tbody></table></div></section><section className="escala-panel"><h3>Folgas por funcionário</h3><p>A composição registrada em cada data é preservada, mesmo depois de transferências e alterações de cadastro.</p><div className="table-wrap"><table><thead><tr><th>Funcionário</th><th>Folgas</th><th>Dias trabalhados</th><th>Rotas programadas</th><th>Rotas realizadas</th></tr></thead><tbody>{[...staff.entries()].map(([id,p])=><tr key={id}><td>{p.name}</td><td>{p.rest}</td><td>{p.work}</td><td>{p.route}</td><td>{p.done}</td></tr>)}</tbody></table></div></section></>;
}

async function downloadPdf(adapter:EscalaAdapter,state:EscalaState,plan:MonthPlan){
 const rules=plan.status!=='DRAFT'&&plan.rules_snapshot?.work_minutes?plan.rules_snapshot:state.rules;const library=window.PDFLib;if(!library)throw Error('O gerador de PDF não foi carregado. Atualize a página.');const {PDFDocument,StandardFonts,rgb}=library,doc=await PDFDocument.create(),font=await doc.embedFont(StandardFonts.Helvetica),bold=await doc.embedFont(StandardFonts.HelveticaBold);let page=doc.addPage([842,595]),y=555;
 const clean=(text:string)=>[...text].map(c=>{try{font.encodeText(c);return c;}catch{return '?';}}).join('');
 const line=(text:string,size=10,strong=false)=>{const f=strong?bold:font;let current='';for(const word of clean(text).split(/\s+/)){if(f.widthOfTextAtSize(current+' '+word,size)>750&&current){draw(current);current=word;}else current+=(current?' ':'')+word;}draw(current);function draw(value:string){if(y<45){page=doc.addPage([842,595]);y=555;}page.drawText(value,{x:42,y,size,font:f,color:rgb(.14,.17,.22)});y-=size+6;}};
 line('ESCALA - '+parseDay(plan.month).toLocaleDateString('pt-BR',{month:'long',year:'numeric',timeZone:'UTC'}),18,true);line(adapter.context().unit+' | '+(plan.status==='DRAFT'?'RASCUNHO':plan.status==='APPROVED'?'APROVADA':'BLOQUEADA')+' | Revisão '+plan.revision);line('Entrada '+hour(rules.start_minute)+' | Trabalho '+hour(rules.work_minutes)+' | Intervalo '+hour(rules.break_minutes));line('Folgas e operação programadas. Rotas realizadas dependem de confirmação explícita.');
 y-=10;const first=weekday(plan.month),cellW=108,cellH=66,startY=y;for(let i=0;i<7;i++)page.drawText(weekdayNames[i].slice(0,3),{x:42+i*cellW,y:startY,font:bold,size:10});for(const [i,day]of plan.days.entries()){const index=first+i,x=42+index%7*cellW,top=startY-20-Math.floor(index/7)*cellH;page.drawRectangle({x,y:top-cellH+5,width:cellW-3,height:cellH-3,borderWidth:.5,borderColor:rgb(.75,.77,.81),color:day.kind==='HOLIDAY'?rgb(.97,.94,.86):rgb(.98,.98,.99)});page.drawText(String(Number(day.date.slice(-2))),{x:x+5,y:top-8,size:10,font:bold});const names=day.duties.filter(d=>d.mode==='REST').map(d=>state.teams.find(t=>t.id===d.team_id)?.code||'');const caption=weekday(day.date)===0?'Todas de folga':names.length>2?names.length+' equipes de folga':names.length?'Folga: '+names.join(', '):'Sem folga';page.drawText(clean(caption),{x:x+5,y:top-24,size:8,font});page.drawText(day.duties.filter(d=>d.mode==='ROUTE').length+' em rota',{x:x+5,y:top-38,size:8,font});}
 page=doc.addPage([842,595]);y=555;line('Detalhamento das equipes e integrantes',16,true);for(const day of plan.days){line(date(day.date)+' - '+weekdayNames[weekday(day.date)]+(day.manual?' | Alteração manual':'')+(day.locked?' | Dia bloqueado':''),11,true);if(day.notes)line('Observação: '+day.notes);for(const duty of day.duties)line((state.teams.find(t=>t.id===duty.team_id)?.name||'Equipe')+' | '+modeNames[duty.mode]+(duty.truck_id?' | '+(state.trucks.find(t=>t.id===duty.truck_id)?.plate||''):'')+' | '+duty.members.map(p=>p.name+' ('+p.job+')').join(', '));y-=8;}
 const issues=plan.status==='DRAFT'?validatePlan(state,plan):[];if(issues.length){line('Pendências da escala em rascunho',13,true);for(const issue of issues)line((issue.date?date(issue.date)+' | ':'')+issue.message);}
 const bytes=await doc.save();await adapter.download(`Escala-${plan.month.slice(0,7)}.pdf`,new Blob([new Uint8Array(bytes)],{type:'application/pdf'}));
}

export function createEscala(adapter:EscalaAdapter){let month=today().slice(0,7)+'-01',dirty=false;let active:View|null=null;const releaseView=(view:View)=>{const element=document.getElementById('view-'+view);if(element)releaseContent(element);};const paint=()=>{if(!active)return;renderContent(document.getElementById('view-'+active),<App key={adapter.context().user?.id+'|'+adapter.context().unit+'|'+active} adapter={adapter} view={active} selectedMonth={month} setSelectedMonth={value=>{month=value;paint();}} onDirty={value=>{dirty=value;}}/>);};return {async enter(view:string){if(!views.includes(view as View))return;if(active&&active!==view)releaseView(active);active=view as View;paint();},start(){},stop(){for(const view of views)releaseView(view);active=null;dirty=false;month=today().slice(0,7)+'-01';},canChangeUnit(){return !dirty||confirm('A escala ainda tem alterações neste aparelho. Trocar de unidade sem enviar ao servidor?');}};}
